package info.u_team.music_player.gui.settings;
import static info.u_team.music_player.init.MusicPlayerLocalization.getTranslation;
import info.u_team.music_player.gui.BetterScreen;import info.u_team.music_player.gui.util.GuiTextCompat;import info.u_team.music_player.gui.widget.UButton;import info.u_team.music_player.musicplayer.MusicPlayerManager;import info.u_team.music_player.musicplayer.settings.Settings;import net.minecraft.client.gui.GuiGraphics;import net.minecraft.client.gui.screens.Screen;import net.minecraft.network.chat.Component;
public final class GuiMiniPlayerLayoutSettings extends BetterScreen{private final Screen previous;private MiniPlayerLayoutWidget editor;public GuiMiniPlayerLayoutSettings(Screen previous){super(Component.literal(getTranslation("gui.layout.title")));this.previous=previous;}@Override protected void init(){final Settings s=MusicPlayerManager.getSettingsManager().getSettings();addRenderableWidget(new UButton(8,8,24,20,Component.literal("<"),b->minecraft.setScreen(previous)));final UButton lock=addRenderableWidget(new UButton(40,8,90,20,lockLabel(s)));lock.setPressable(()->{s.setMiniPlayerLocked(!s.isMiniPlayerLocked());lock.setMessage(lockLabel(s));});final UButton snap=addRenderableWidget(new UButton(136,8,90,20,snapLabel(s)));snap.setPressable(()->{s.setMiniPlayerSnapToEdges(!s.isMiniPlayerSnapToEdges());snap.setMessage(snapLabel(s));});addRenderableWidget(new UButton(232,8,80,20,Component.literal(getTranslation("gui.layout.reset")),b->{s.resetMiniPlayerPlacement();minecraft.setScreen(new GuiMiniPlayerLayoutSettings(previous));}));editor=new MiniPlayerLayoutWidget(width,height);addWidget(editor);}@Override public void render(GuiGraphics g,int mx,int my,float pt){super.render(g,mx,my,pt);editor.render(g,mx,my,pt);GuiTextCompat.draw(g,font,getTranslation("gui.layout.hint"),12,height-12,0xCBD5DF,false);}private static Component lockLabel(Settings s){return label("gui.layout.lock",s.isMiniPlayerLocked());}private static Component snapLabel(Settings s){return label("gui.layout.snap",s.isMiniPlayerSnapToEdges());}private static Component label(String key,boolean enabled){return Component.literal(getTranslation(key)+": "+getTranslation(enabled?"gui.settings.state.on":"gui.settings.state.off"));}}
